     1→import { useEffect } from "react";
     2→import { useLocation } from "react-router-dom";
     3→import { useSeoSettings, useSeoPages } from "@/hooks/useSeoSettings";
     4→
     5→/**
     6→ * Dynamic SEO head manager.
     7→ * Updates document meta tags based on admin-configured SEO settings.
     8→ * Supports per-page overrides that fall back to global settings.
     9→ */
    10→const SeoHead = () => {
    11→  const location = useLocation();
    12→  const { settings } = useSeoSettings();
    13→  const { pages } = useSeoPages();
    14→
    15→  useEffect(() => {
    16→    if (!settings) return;
    17→
    18→    const currentPage = pages.find((p) => p.page_path === location.pathname && p.is_active);
    19→
    20→    // Resolve with per-page overrides falling back to global
    21→    const title = currentPage?.title || settings.site_title || "Instant Resume Ranker";
    22→    const description = currentPage?.description || settings.site_description || "";
    23→    const keywords = currentPage?.keywords || settings.site_keywords || "";
    24→    const robots = currentPage?.meta_robots || settings.meta_robots || "index, follow";
    25→    // Per-page canonical is used as-is; global canonical is a base URL + current path
    26→    const canonicalBase = (settings.canonical_url || "").replace(/\/$/, "");
    27→    const canonical = currentPage?.canonical_url ||
    28→      (canonicalBase ? `${canonicalBase}${location.pathname}` : "");
    29→    const ogTitle = currentPage?.og_title || settings.og_title || title;
    30→    const ogDescription = currentPage?.og_description || settings.og_description || description;
    31→    const ogImage = currentPage?.og_image_url || settings.og_image_url || "";
    32→    const ogType = settings.og_type || "website";
    33→    const ogSiteName = settings.og_site_name || settings.site_title || "";
    34→    const twitterCard = settings.twitter_card || "summary_large_image";
    35→    const twitterSite = settings.twitter_site || "";
    36→    const twitterCreator = settings.twitter_creator || "";
    37→    const twitterImage = settings.twitter_image_url || ogImage;
    38→
    39→    // Update document title
    40→    document.title = title;
    41→
    42→    // Helper to set/remove a meta tag
    43→    const setMeta = (attr: string, key: string, content: string) => {
    44→      if (!content) {
    45→        const existing = document.querySelector(`meta[${attr}="${key}"]`);
    46→        if (existing) existing.remove();
    47→        return;
    48→      }
    49→      let el = document.querySelector(`meta[${attr}="${key}"]`) as HTMLMetaElement;
    50→      if (!el) {
    51→        el = document.createElement("meta");
    52→        el.setAttribute(attr, key);
    53→        document.head.appendChild(el);
    54→      }
    55→      el.setAttribute("content", content);
    56→    };
    57→
    58→    // Standard meta
    59→    setMeta("name", "description", description);
    60→    setMeta("name", "keywords", keywords);
    61→    setMeta("name", "robots", robots);
    62→    setMeta("name", "theme-color", settings.theme_color || "");
    63→
    64→    // Bot-specific meta
    65→    if (settings.googlebot) setMeta("name", "googlebot", settings.googlebot);
    66→    if (settings.bingbot) setMeta("name", "bingbot", settings.bingbot);
    67→
    68→    // Verification meta
    69→    if (settings.google_search_console_id) setMeta("name", "google-site-verification", settings.google_search_console_id);
    70→    if (settings.bing_webmaster_id) setMeta("name", "msvalidate.01", settings.bing_webmaster_id);
    71→
    72→    // Open Graph
    73→    setMeta("property", "og:title", ogTitle);
    74→    setMeta("property", "og:description", ogDescription);
    75→    setMeta("property", "og:image", ogImage);
    76→    setMeta("property", "og:type", ogType);
    77→    setMeta("property", "og:site_name", ogSiteName);
    78→    if (canonical) setMeta("property", "og:url", canonical);
    79→    if (settings.facebook_app_id) setMeta("property", "fb:app_id", settings.facebook_app_id);
    80→
    81→    // Twitter Card
    82→    setMeta("name", "twitter:card", twitterCard);
    83→    setMeta("name", "twitter:title", ogTitle);
    84→    setMeta("name", "twitter:description", ogDescription);
    85→    setMeta("name", "twitter:image", twitterImage);
    86→    if (twitterSite) setMeta("name", "twitter:site", twitterSite);
    87→    if (twitterCreator) setMeta("name", "twitter:creator", twitterCreator);
    88→
    89→    // Sitemap link (always points to /sitemap.xml on the same domain)
    90→    if (!document.querySelector('link[rel="sitemap"]')) {
    91→      const linkSitemap = document.createElement("link");
    92→      linkSitemap.setAttribute("rel", "sitemap");
    93→      linkSitemap.setAttribute("type", "application/xml");
    94→      linkSitemap.setAttribute("title", "Sitemap");
    95→      linkSitemap.setAttribute("href", "/sitemap.xml");
    96→      document.head.appendChild(linkSitemap);
    97→    }
    98→
    99→    // Canonical link
   100→    let linkCanonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement;
   101→    if (canonical) {
   102→      if (!linkCanonical) {
   103→        linkCanonical = document.createElement("link");
   104→        linkCanonical.setAttribute("rel", "canonical");
   105→        document.head.appendChild(linkCanonical);
   106→      }
   107→      linkCanonical.setAttribute("href", canonical);
   108→    } else if (linkCanonical) {
   109→      linkCanonical.remove();
   110→    }
   111→
   112→    // Structured Data (JSON-LD)
   113→    const existingLd = document.getElementById("seo-jsonld");
   114→    if (settings.structured_data_enabled) {
   115→      const schemas: Record<string, any>[] = [];
   116→
   117→      // Organization schema
   118→      const org: Record<string, any> = {
   119→        "@context": "https://schema.org",
   120→        "@type": "Organization",
   121→        name: settings.organization_name || settings.site_title || "Instant Resume Ranker",
   122→        description: settings.organization_description || description,
   123→      };
   124→      if (settings.organization_url) org.url = settings.organization_url;
   125→      if (settings.organization_logo_url) org.logo = settings.organization_logo_url;
   126→      schemas.push(org);
   127→
   128→      // WebApplication schema
   129→      const webapp: Record<string, any> = {
   130→        "@context": "https://schema.org",
   131→        "@type": "WebApplication",
   132→        name: settings.site_title || "Instant Resume Ranker",
   133→        description: description,
   134→        applicationCategory: "BusinessApplication",
   135→        operatingSystem: "Web",
   136→      };
   137→      if (settings.organization_url) webapp.url = settings.organization_url;
   138→      schemas.push(webapp);
   139→
   140→      // Per-page structured data
   141→      if (currentPage?.structured_data_json && Object.keys(currentPage.structured_data_json).length > 0) {
   142→        schemas.push(currentPage.structured_data_json);
   143→      }
   144→
   145→      const script = existingLd || document.createElement("script");
   146→      script.setAttribute("type", "application/ld+json");
   147→      script.id = "seo-jsonld";
   148→      script.textContent = JSON.stringify(schemas);
   149→      if (!existingLd) document.head.appendChild(script);
   150→    } else if (existingLd) {
   151→      existingLd.remove();
   152→    }
   153→
   154→    // ── AEO (Answer Engine Optimization) ──────────────────────────────────
   155→    // Remove existing AEO script so it can be replaced cleanly on updates
   156→    document.getElementById("seo-aeo-faq-jsonld")?.remove();
   157→    if (settings.aeo_enabled) {
   158→      const faqItems = Array.isArray(settings.aeo_faq_json) ? settings.aeo_faq_json : [];
   159→
   160→      if (faqItems.length > 0) {
   161→        const faqSchema = {
   162→          "@context": "https://schema.org",
   163→          "@type": "FAQPage",
   164→          mainEntity: faqItems.map((item: { q: string; a: string }) => ({
   165→            "@type": "Question",
   166→            name: item.q,
   167→            acceptedAnswer: { "@type": "Answer", text: item.a },
   168→          })),
   169→        };
   170→        const faqScript = document.createElement("script");
   171→        faqScript.setAttribute("type", "application/ld+json");
   172→        faqScript.id = "seo-aeo-faq-jsonld";
   173→        faqScript.textContent = JSON.stringify(faqSchema);
   174→        document.head.appendChild(faqScript);
   175→      }
   176→
   177→      // Re-inject the main seo-jsonld WebApplication schema with speakable if enabled
   178→      if (settings.aeo_speakable_enabled && settings.structured_data_enabled) {
   179→        const existingLdScript = document.getElementById("seo-jsonld");
   180→        if (existingLdScript) {
   181→          try {
   182→            const schemas = JSON.parse(existingLdScript.textContent || "[]") as Record<string, any>[];
   183→            const webappIdx = schemas.findIndex((s) => s["@type"] === "WebApplication");
   184→            if (webappIdx !== -1) {
   185→              schemas[webappIdx].speakable = {
   186→                "@type": "SpeakableSpecification",
   187→                cssSelector: ["h1", "h2", ".speakable"],
   188→              };
   189→              existingLdScript.textContent = JSON.stringify(schemas);
   190→            }
   191→          } catch {
   192→            // JSON parse failed — leave schema as-is
   193→          }
   194→        }
   195→      }
   196→    }
   197→
   198→    // ── GEO (Generative Engine Optimization) ──────────────────────────────
   199→    const currentYear = new Date().getFullYear().toString();
   200→    const siteTitle = settings.site_title || "Instant Resume Ranker";
   201→
   202→    if (settings.geo_enabled) {
   203→      setMeta("name", "generator", "Rankora");
   204→      if (settings.geo_author_name) {
   205→        setMeta("name", "citation_author", settings.geo_author_name);
   206→      } else {
   207→        document.querySelector('meta[name="citation_author"]')?.remove();
   208→      }
   209→      setMeta("name", "citation_publication_date", currentYear);
   210→      if (settings.geo_site_description_for_ai) {
   211→        setMeta("name", "description_ai", settings.geo_site_description_for_ai);
   212→      } else {
   213→        document.querySelector('meta[name="description_ai"]')?.remove();
   214→      }
   215→      if (settings.geo_citations_enabled) {
   216→        setMeta("name", "citation_title", siteTitle);
   217→        setMeta("name", "robots", "max-snippet:-1, max-image-preview:large, index, follow");
   218→      } else {
   219→        document.querySelector('meta[name="citation_title"]')?.remove();
   220→      }
   221→    } else {
   222→      // Clean up GEO meta tags if disabled
   223→      ["generator", "citation_author", "citation_publication_date", "description_ai", "citation_title"]
   224→        .forEach((name) => document.querySelector(`meta[name="${name}"]`)?.remove());
   225→    }
   226→
   227→    // Google Analytics — reinject if ID changes or was removed
   228→    const existingGaScript = document.getElementById("ga-script") as HTMLScriptElement | null;
   229→    if (settings.google_analytics_id) {
   230→      const newSrc = `https://www.googletagmanager.com/gtag/js?id=${settings.google_analytics_id}`;
   231→      if (existingGaScript && existingGaScript.src !== newSrc) {
   232→        // GA ID changed — remove old scripts so they get recreated
   233→        existingGaScript.remove();
   234→        document.getElementById("ga-init")?.remove();
   235→      }
   236→      if (!document.getElementById("ga-script")) {
   237→        const gaScript = document.createElement("script");
   238→        gaScript.id = "ga-script";
   239→        gaScript.async = true;
   240→        gaScript.src = newSrc;
   241→        document.head.appendChild(gaScript);
   242→        const gaInit = document.createElement("script");
   243→        gaInit.id = "ga-init";
   244→        gaInit.textContent = `window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config','${settings.google_analytics_id}');`;
   245→        document.head.appendChild(gaInit);
   246→      }
   247→    } else {
   248→      // GA ID cleared — clean up scripts
   249→      document.getElementById("ga-script")?.remove();
   250→      document.getElementById("ga-init")?.remove();
   251→    }
   252→  }, [settings, pages, location.pathname]);
   253→
   254→  return null;
   255→};
   256→
   257→export default SeoHead;
   258→

