     9→import { toast } from "sonner";
    10→import { Save, Loader2, Globe } from "lucide-react";
    11→import { logAuditAction } from "@/lib/auditLog";
    12→
    13→const GlobalSeoTab = () => {
    14→  const qc = useQueryClient();
    15→  const { settings, isLoading } = useSeoSettings();
    16→  const [saving, setSaving] = useState(false);
    17→  const [loaded, setLoaded] = useState(false);
    18→
    19→  const [form, setForm] = useState({
    20→    site_title: "",
    21→    site_description: "",
    22→    site_keywords: "",
    23→    canonical_url: "",
    24→    meta_robots: "index, follow",
    25→    theme_color: "#8b5cf6",
    26→    google_analytics_id: "",
    27→    google_search_console_id: "",
    28→    bing_webmaster_id: "",
    29→    facebook_app_id: "",
    30→  });
    31→
    32→  if (settings && !loaded) {
    33→    setForm({
    34→      site_title: settings.site_title ?? "",
    35→      site_description: settings.site_description ?? "",
    36→      site_keywords: settings.site_keywords ?? "",
    37→      canonical_url: settings.canonical_url ?? "",
    38→      meta_robots: settings.meta_robots ?? "index, follow",
    39→      theme_color: settings.theme_color ?? "#8b5cf6",
    40→      google_analytics_id: settings.google_analytics_id ?? "",
    41→      google_search_console_id: settings.google_search_console_id ?? "",
    42→      bing_webmaster_id: settings.bing_webmaster_id ?? "",
    43→      facebook_app_id: settings.facebook_app_id ?? "",
    44→    });
    45→    setLoaded(true);
    46→  }
    47→
    48→  const save = async () => {
    49→    if (!form.site_title.trim()) { toast.error("Site title is required"); return; }
    50→    if (!form.site_description.trim()) { toast.error("Site description is required"); return; }
    51→    setSaving(true);
    52→    try {
    53→      const { error } = await (supabase as any)
    54→        .from("seo_settings")
    55→        .update(form)
    56→        .eq("id", settings?.id);
    57→      if (error) { toast.error(error.message); return; }
    58→      toast.success("Global SEO settings saved");
    59→      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "global", ...form });
    60→      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    61→    } finally {
    62→      setSaving(false);
    63→    }
    64→  };
    65→
    66→  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;
    67→
    68→  return (
    69→    <div className="space-y-4">
    70→      <Card>
    71→        <CardHeader className="pb-3">
    72→          <CardTitle className="text-lg flex items-center gap-2"><Globe className="h-5 w-5" /> Global Meta Tags</CardTitle>
    73→          <CardDescription>These are the default meta tags for all pages unless overridden per-page.</CardDescription>
    74→        </CardHeader>
    75→        <CardContent className="space-y-4">
    76→          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
